// Hub 1 - check every approved post BEFORE anything is scheduled
const cfg = $('Config').first().json;
const CHANNELS = { 'X': cfg.xChannelId, 'Bluesky': cfg.blueskyChannelId };
const LIMITS = { 'X': 280, 'Bluesky': 300 };
const allowed = String(cfg.allowedApprovers || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const runId = 'run-' + $execution.id;
const txt = (p) => ((p && (p.rich_text || p.title)) || []).map(t => t.plain_text).join('');
const out = [];

const rows = ($input.first().json.results) || [];
for (const page of rows) {
  const pr = page.properties || {};
  const approvers = ((pr['Approved by'] || {}).people || []);
  const approverLabel = approvers.map(a => a.name || (a.person && a.person.email) || 'someone').join(', ');
  const base = { pageId: page.id, url: page.url, title: txt(pr['Title']) || '(untitled)', runId, approver: approverLabel };
  const reject = (reason) => out.push({ json: { ...base, type: 'reject', reason } });

  const postText = txt(pr['Post text']).trim();
  const platforms = ((pr['Platforms'] || {}).multi_select || []).map(o => o.name);
  let publishAt = ((pr['Publish at'] || {}).date || {}).start || null;

  // what is already scheduled, stored as "X=abc; Bluesky=def"
  const done = {};
  txt(pr['Publisher ID']).split(';').forEach(s => { const [k, v] = s.split('='); if (k && v) done[k.trim()] = v.trim(); });

  if (!postText) { reject('The post text is empty.'); continue; }
  if (!platforms.length) { reject("No platform is chosen under 'Platforms'."); continue; }
  const unsupported = platforms.filter(p => !CHANNELS[p]);
  if (unsupported.length) { reject('These platforms are not connected yet: ' + unsupported.join(', ') + '.'); continue; }
  if (!publishAt) { reject("There is no 'Publish at' time."); continue; }
  if (publishAt.length <= 10) { reject("'Publish at' needs a time as well as a date."); continue; }
  if (!/(Z|[+-]\d\d:\d\d)$/.test(publishAt)) publishAt += (cfg.timezoneOffset || '+05:30');
  const due = new Date(publishAt);
  const len = [...postText].length;
  const todo = platforms.filter(p => !done[p]);
  if (todo.length && (isNaN(due) || due.getTime() < Date.now() + 60000)) { reject("The 'Publish at' time has passed or is less than a minute away. Pick a later time."); continue; }
  const tooLong = platforms.filter(p => len > LIMITS[p]);
  if (tooLong.length) { reject('The post has ' + len + ' characters, which is over the limit for ' + tooLong.map(p => p + ' (' + LIMITS[p] + ')').join(' and ') + '.'); continue; }
  if (!approvers.length) { reject("Nobody is listed under 'Approved by'. Posts only go out with a named approver."); continue; }
  if (allowed.length) {
    const ok = approvers.some(a => allowed.includes(String(a.name || '').toLowerCase()) || allowed.includes(String((a.person || {}).email || '').toLowerCase()));
    if (!ok) { reject(approverLabel + ' is not on the list of people who can approve posts.'); continue; }
  }

  if (!todo.length) { out.push({ json: { ...base, type: 'skip', done } }); continue; }
  for (const p of todo) {
    const query = 'mutation { createPost(input: { text: ' + JSON.stringify(postText) + ', channelId: "' + CHANNELS[p] + '", schedulingType: automatic, mode: customScheduled, dueAt: "' + due.toISOString() + '" }) { ... on PostActionSuccess { post { id status dueAt } } ... on MutationError { message } } }';
    out.push({ json: { ...base, type: 'schedule', platform: p, dueAt: due.toISOString(), done, platforms, query } });
  }
}
return out;

// Hub 1 - turn rejected / duplicate posts into: Notion update + Slack alert + log row
const cfg = $('Config').first().json;
const rt = (s) => ({ rich_text: [{ text: { content: String(s).slice(0, 1900) } }] });
const logBody = (event, d, detail) => ({ parent: { database_id: cfg.logDbId }, properties: {
  'Run': { title: [{ text: { content: d.runId + ' ' + event } }] }, 'System': rt('Publishing Hub'), 'Item': rt(d.title),
  'Event': { select: { name: event } }, 'Detail': rt(detail), 'Model': rt('none (no AI step)'), 'Cost': { number: 0 }, 'Approver': rt(d.approver || '') } });
const A = [];
for (const it of $input.all()) {
  const d = it.json;
  if (d.type === 'reject') {
    A.push({ json: { type: 'notion', pageId: d.pageId, body: { properties: { 'Status': { select: { name: 'In review' } }, 'Last error': rt('Not scheduled: ' + d.reason) } } } });
    A.push({ json: { type: 'slack', webhook: cfg.slackWebhook, text: ':warning: *' + d.title + '* was not scheduled. ' + d.reason + ' I moved it back to "In review". Fix it and set it to Approved again.\n<' + d.url + '|Open in Notion>' } });
    A.push({ json: { type: 'log', body: logBody('rejected', d, d.reason) } });
  } else if (d.type === 'skip') {
    A.push({ json: { type: 'notion', pageId: d.pageId, body: { properties: { 'Status': { select: { name: 'Scheduled' } }, 'Last error': rt('Approved a second time. Ignored, because it is already scheduled.') } } } });
    A.push({ json: { type: 'slack', webhook: cfg.slackWebhook, text: ':information_source: *' + d.title + '* was approved a second time, but it is already scheduled. I ignored it so it will not post twice.\n<' + d.url + '|Open in Notion>' } });
    A.push({ json: { type: 'log', body: logBody('skipped', d, 'Duplicate approval ignored. Already scheduled: ' + JSON.stringify(d.done)) } });
  }
}
return A;

// Hub 1 - read Buffer's answers and decide: Scheduled or Failed
const cfg = $('Config').first().json;
const rt = (s) => ({ rich_text: [{ text: { content: String(s).slice(0, 1900) } }] });
const logBody = (event, d, detail) => ({ parent: { database_id: cfg.logDbId }, properties: {
  'Run': { title: [{ text: { content: d.runId + ' ' + event } }] }, 'System': rt('Publishing Hub'), 'Item': rt(d.title),
  'Event': { select: { name: event } }, 'Detail': rt(detail), 'Model': rt('none (no AI step)'), 'Cost': { number: 0 }, 'Approver': rt(d.approver || '') } });
const plain = (m) => {
  if (/401|unauthor|token|api key|authenticat/i.test(m)) return "Buffer rejected our key. The key may have been replaced or revoked. Make a new key in Buffer and update it in n8n (Runbook, fix 1).";
  if (/limit|quota/i.test(m)) return 'Buffer says a queue or plan limit was reached. Wait for some posts to go out, or upgrade the plan. (Buffer said: ' + m + ')';
  if (/disconnect|reconnect|expired/i.test(m)) return 'The channel looks disconnected in Buffer. Reconnect it in Buffer, then approve again. (Buffer said: ' + m + ')';
  return 'Buffer said: ' + m;
};
const asked = $('Check each post').all().map(i => i.json).filter(d => d.type === 'schedule');
const answers = $input.all().map(i => i.json);
const groups = {};
asked.forEach((d, i) => {
  const r = answers[i] || {};
  const cp = r.data && r.data.createPost;
  const id = cp && cp.post && cp.post.id;
  const g = groups[d.pageId] = groups[d.pageId] || { d, ids: { ...d.done }, fails: [] };
  if (id) g.ids[d.platform] = id;
  else {
    const e = r.error;
    const msg = (cp && cp.message) || (r.errors && r.errors[0] && r.errors[0].message) || (e && (e.message || String(e))) || 'no answer from Buffer';
    g.fails.push(d.platform + ': ' + plain(String(msg)));
  }
});
const A = [];
for (const g of Object.values(groups)) {
  const d = g.d;
  const serial = Object.entries(g.ids).map(([k, v]) => k + '=' + v).join('; ');
  const idsProp = serial ? rt(serial) : { rich_text: [] };
  if (!g.fails.length) {
    A.push({ json: { type: 'notion', pageId: d.pageId, body: { properties: { 'Status': { select: { name: 'Scheduled' } }, 'Publisher ID': idsProp, 'Run key': rt(d.runId), 'Last error': { rich_text: [] } } } } });
    A.push({ json: { type: 'log', body: logBody('scheduled', d, 'Scheduled for ' + d.dueAt + ' on ' + Object.keys(g.ids).join(' + ') + ' (' + serial + ')') } });
  } else {
    const okPlatforms = Object.keys(g.ids);
    const text = g.fails.join(' | ') + (okPlatforms.length ? ' Already scheduled: ' + okPlatforms.join(', ') + '. Set the status to Approved again to retry only the missing ones.' : ' Fix the problem, then set the status to Approved again.');
    A.push({ json: { type: 'notion', pageId: d.pageId, body: { properties: { 'Status': { select: { name: 'Failed' } }, 'Publisher ID': idsProp, 'Run key': rt(d.runId), 'Last error': rt('Could not schedule. ' + text) } } } });
    A.push({ json: { type: 'slack', webhook: cfg.slackWebhook, text: ':rotating_light: *' + d.title + '* failed to schedule. ' + text + '\n<' + d.url + '|Open in Notion>' } });
    A.push({ json: { type: 'log', body: logBody('failed', d, text) } });
  }
}
return A;
